{
  "name": "Concentrations of Antibodies Against Hepatitis B (Anti-HB)",
  "endpoint_type": "primary",
  "definition": "Concentrations were expressed as geometric mean concentrations (GMCs) in milli-international unit per milliliter (mIU/mL). The cut-off of the assay was the seroprotection cut-off of 10 mIU/mL. Month 3 results are the specific results for this primary outcome measure."
}

{
  "name": "Concentrations of Antibodies Against Diphtheria (Anti-D)",
  "endpoint_type": "primary",
  "definition": "Antibodies were measured by Enzyme-linked immunosorbent assay (ELISA). Concentrations were expressed as geometric mean concentrations (GMCs) in international unit per milliliter (IU/mL). The cut-off of the assay was the seroprotection cut-off of 0.1 IU/mL. Month 3 results are the specific results for this primary outcome measure."
}

{
  "name": "Concentrations of Antibodies Against Tetanus (Anti-T)",
  "endpoint_type": "primary",
  "definition": "Antibodies were measured by Enzyme-linked immunosorbent assay (ELISA). Concentrations were expressed as geometric mean concentrations (GMCs) in international unit per milliliter (IU/mL). The cut-off of the assay was the seroprotection cut-off of 0.1 IU/mL. Month 3 results are the specific results for this primary outcome measure."
}

{
  "name": "Concentrations of Anti-polyribosyl Ribitol Phosphate Antibodies (Anti-PRP)",
  "endpoint_type": "primary",
  "definition": "Concentrations were expressed as geometric mean concentrations (GMCs) in microgram per milliliter (\u00b5g/mL). The cut-off of the assay is the seroprotection cut-off value of 0.15 \u00b5g/mL. Month 3 results are the specific results for this primary outcome measure."
}

{
  "name": "Concentrations of Anti-Bordetella Pertussis Toxin Antibodies (Anti-BPT)",
  "endpoint_type": "primary",
  "definition": "Antibodies were measured by Enzyme-linked immunosorbent assay (ELISA). Concentrations were expressed as geometric mean concentrations (GMCs) in ELISA unit per milliliter (EL.U/mL). The cut-off of the assay was the seropositivity cut-off of 15 EL.U/mL. Month 3 results are the specific results for this primary outcome measure."
}

{
  "name": "Number of Subjects With Hepatitis B Antibody (Anti-HB) Concentrations Equal to or Above (>=) the Seroprotection Cut-off Value",
  "endpoint_type": "primary",
  "definition": "The seroprotection cut-off value was 10 milli-international units per milliliter (mIU/mL). Blood samples were collected prior to vaccination at Week 0 (PRE), at Month 2 and at Month 3. Month 3 results are the specific results for this primary outcome measure."
}

{
  "name": "Number of Subjects With Anti-diphtheria Antibody (Anti-D) Concentrations Equal to or Above (>=) the Seroprotection Cut-off Value",
  "endpoint_type": "primary",
  "definition": "Antibodies were measured by Enzyme-linked immunosorbent assay (ELISA). The seroprotection cut-off value was 0.1 international unit per milliliter (IU/mL). Blood samples were collected prior to vaccination at Week 0 (PRE), and at Month 3. Month 3 results are the specific results for this primary outcome measure."
}

{
  "name": "Number of Subjects With Anti-tetanus Antibody (Anti-T) Concentrations Equal to or Above (>=) the Seroprotection Cut-off Value",
