}

{
  "name": "Number of Subjects With Anti-Bordetella Pertussis Toxin Antibody (Anti-BPT) Concentrations Equal to or Above (>=) the Seropositivity Cut-off Value",
  "endpoint_type": "primary",
  "definition": "Antibodies were measured by Enzyme-linked immunosorbent assay (ELISA). The seropositivity cut-off value was 15 ELISA units per milliliter (EL.U/mL). Blood samples were collected prior to vaccination at Week 0 (PRE), and at Month 3. Month 3 results are the specific results for this primary outcome measure."
}

{
  "name": "Mean Percent Days of Total Shedding (Clinical and Subclinical) as Determined by Type-specific Polymerase Chain Reaction (PCR) Assay for Herpes Simplex Virus Type 2 (HSV-2)",
  "endpoint_type": "primary",
  "definition": "Each participant's study day were classified as either 'shedding' (positive HSV-2 result), 'no shedding' (negative HSV-2 result), or 'unknown' (swabbing not done or assay result not available) confirmed by PCR. If either the daily genital swab or a lesion swab are positive, the day was classified as 'shedding'. Study shedding day was classified as either 'clinical' (investigator-confirmed presence of genital lesions) or 'subclinical' (no genital lesions) by the investigator during recurrence vis"
}

{
  "name": "Overall Survival",
  "endpoint_type": "primary",
  "definition": "Death from any cause which occurred from the day of starting IP until the Common End Date (CED). Common End Date (CED) is the study end date that was pre determined where approximately 1000 deaths would have occurred in the Intent-to-Treat Efficacy (ITT-E) Population. Only deaths which occurred on or before the CED were used for the primary analysis. Those who had not died by CED, but who were known to be alive on or after the CED, were censored at the CED."
}

