{
  "name": "Number of Participants With Any Adverse Event (AE) or Serious Adverse Event (SAE)",
  "endpoint_type": "primary",
  "definition": "An AE is defined as any untoward medical occurrence in a participant, temporally associated with the use of a medicinal product, whether or not considered related to the medicinal product. An SAE is defined as any untoward medical occurrence that, at any dose, results in death, is life-threatening, requires hospitalization or prolongation of existing hospitalization, results in disability/incapacity, or is a congenital anomaly/birth defect, may jeopardize the participant or may require medical o"
}

{
  "name": "Adverse events",
  "endpoint_type": "primary",
  "definition": "Adverse events. Changes suggesting potential adverse events detected in the physical & neurological examination, brain MRI, cognitive status, laboratory parameters, ECG & vital signs."
}

