}

{
  "name": "Number of Seroconverted Subjects",
  "endpoint_type": "primary",
  "definition": "Seroconverted subjects are defined as subjects with either a pre-vaccination HI titer <1:10 and a post-vaccination titer \u2265 1:40, or a pre-vaccination titer \u2265 1:10 and a minimum 4-fold increase at post-vaccination titer. Data are presented for all 3 viral strains comprised in the vaccine."
}

{
  "name": "Number of Subjects Reporting Rare Serious Events",
  "endpoint_type": "primary",
  "definition": "Rare serious event is defined as any untoward medical event with an occurrence rate of \u22651/300 that: resulted in death, was life-threatening, required hospitalization or prolongation of existing hospitalization, resulted in disability/incapacity, or was a congenital anomaly/birth defect in the offspring of a study subject."
}

{
  "name": "SLE Responder Index (SRI) Response Rate",
  "endpoint_type": "primary",
  "definition": "Percentage of participants achieving a SLE Responder Index (SRI) response at Week 52, where SRI response is defined as >=4 point reduction from Baseline in SELENA SLEDAI score, no worsening (increase of <0.30 points from Baseline) in physician's global assessment (PGA) and no new BILAG A organ domain score or 2 new BILAG B organ domain scores compared with Baseline"
}

{
  "name": "Safety and tolerability",
  "endpoint_type": "primary",
  "definition": "Electrocardiogram, vital signs, lab tests, AEs and nasal tolerability"
}

{
  "name": "Number of Participants With Adverse Events (AE) and Serious Adverse Events (SAE)",
  "endpoint_type": "primary",
  "definition": "AE is any untoward medical occurrence in a participant or clinical investigation participant, temporally associated with the use of a medicinal product, whether or not considered related to the medicinal product. An AE can therefore be any unfavorable and unintended sign (including an abnormal laboratory finding), symptom, or disease (new or exacerbated) temporally associated with the use of a medicinal product. For marketed medicinal products, this also includes failure to produce expected bene"
}

{
  "name": "Summary of Mean Systolic Blood Pressure (SBP) and Diastolic Blood Pressure (DBP)",
  "endpoint_type": "primary",
  "definition": "Blood pressure was measured subsequent to 12 lead electrocardiogram (ECG). Baseline was defined as the mean of the three planned pre-dose measurements. It was assessed on Baseline (triplicate), 15, 30 minutes, 1.5, 4, 8 and 24 hours on Day 1 and 7."
}

{
  "name": "Summary of Mean Heart Rate",
  "endpoint_type": "primary",
  "definition": "Heart rate was measured subsequent to 12 lead ECG. Baseline was defined as the mean of the three planned pre-dose measurements. It was assessed on Baseline (triplicate), 15, 30 minutes, 1.5, 4, 8 and 24 hours on Day 1 and 7."
}

{
  "name": "Maximum Value of SBP and DBP (0-4 Hour) for the Morning Dose",
  "endpoint_type": "primary",
  "definition": "Blood pressure was measured subsequent to 12 lead ECG. Baseline was defined as the mean of the three planned pre-dose measurements. It was assessed on pre-dose, 15, 30 minutes, 1.5 and 4 hours on Day 1 and 7. Data for adjusted mean is presented as least square mean."
}

{
  "name": "Maximum Value of Heart Rate (0-4 Hour) for the Morning Dose",
  "endpoint_type": "primary",
  "definition": "Heart rate was measured subsequent to 12 lead ECG. Baseline was defined as the mean of the three planned pre-dose measurements. It was assessed on pre-dose, 15, 30 minutes, 1.5 and 4 hours on Day 1 and 7. Data for adjusted mean is presented as least square mean."
}

{
  "name": "Weighted Mean of SBP and DBP (0-4 Hour) for the Morning Dose",
  "endpoint_type": "primary",
  "definition": "Blood pressure was measured subsequent to 12 lead ECG. Baseline was defined as the mean of the three planned pre-dose measurements. It was assessed on pre-dose, 15, 30 minutes, 1.5 and 4 hours on Day 1 and 7. Data for adjusted mean is presented as least square mean."
}

{
  "name": "Weighted Mean of Heart Rate (0-4 Hour) for the Morning Dose",
  "endpoint_type": "primary",
  "definition": "Heart rate was measured subsequent to 12 lead ECG. Baseline was defined as the mean of the three planned pre-dose measurements. It was assessed on pre-dose, 15, 30 minutes, 1.5 and 4 hours on Day 1 and 7. Data for adjusted mean is presented as least square mean."
}

{
  "name": "Number of Participants With Abnormal 12-lead ECG Findings",
  "endpoint_type": "primary",
  "definition": "Single measurements were taken at all time points. The pre-dose values were classed as Baseline. Data for number of participants with normal, abnormal not clinically significant and abnormal clinically significant is presented. It was assessed on Baseline (triplicate), 15, 30 minutes, 1.5, 4, 8 and 24 hours on Day 1 and 7."
}

{
  "name": "Maximum Value (0-4 Hour) for the Morning Dose of ECG Parameters Corrected According to Fredericia's Formula (QTcF) and Corrected According to Bazett's Formula (QTc B)",
  "endpoint_type": "primary",
  "definition": "Baseline was defined as the mean of the three planned pre-dose measurements. It was assessed on pre-dose, 15, 30 minutes, 1.5 and 4 hours on Day 1 and 7. Data for adjusted mean is presented as least square mean."
}

{
  "name": "Weighted Mean (0-4 h) for the Morning Dose of ECG Parameters QTcF and QTc B",
  "endpoint_type": "primary",
  "definition": "Baseline was defined as the mean of the three planned pre-dose measurements. It was assessed on pre-dose, 15, 30 minutes, 1.5 and 4 hours on Day 1 and 7. Data for adjusted mean is presented as least square mean."
}

{
  "name": "Summary of Mean Forced Expiratory Volume in 1 Second (FEV1) and Forced Vital Capacity (FVC)",
  "endpoint_type": "primary",
  "definition": "It was assessed on 1, 2, 4, 9, 12 and 24 hours on Days 1 and 7. Also on Day 7, it was measured on 0 hour (Baseline). At all time points 3 measurements were taken and formal statistical analysis was carried out on the derived maximum readings. Data for adjusted mean is presented as least square mean."
}

{
  "name": "Number of Participants Who Used Rescue Medication",
  "endpoint_type": "primary",
  "definition": "Inhaled salbutamol was used as a rescue medication. Participants were required to keep a diary of their rescue medication (total number of salbutamol doses taken) over the entire 7-day treatment period. Diaries were reviewed by the Investigator when participants were admitted to the unit on Days 1, 2, 7 and 8."
}

{
