  "definition": "Proportion of patients with best overall response of Complete Response, Partial Response, or Stable Disease per RECIST v1.1"
}

{
  "name": "Time to first symptomatic skeletal event (SSE)",
  "endpoint_type": "Key Secondary",
  "definition": "Time from randomization to first new symptomatic pathological bone fracture, spinal cord compression, tumor-related orthopedic surgical intervention, requirement for radiation therapy to relieve bone pain, or death due to any cause"
}

{
  "name": "Progression-free survival (PFS)",
  "endpoint_type": "Additional Secondary",
  "definition": "Time from randomization to first evidence of radiographic, clinical or PSA progression or death due to any cause"
}

{
  "name": "SUV change correlation with pCR",
  "endpoint_type": "Primary",
  "definition": "To correlate baseline and change (day 15) in SUV on FDG PET with pathological complete response (pCR) in patients treated with preoperative pertuzumab/trastuzumab"
}

{
  "name": "PIK3CA mutation correlation with pCR",
  "endpoint_type": "Secondary",
  "definition": "To correlate PIK3CA mutation status and other genomic alterations (mutations/somatic rearrangements) qualitatively and quantitatively in plasma tumor DNA (ptDNA) with pCR"
}

{
  "name": "PI3K pathway activation correlation with pCR",
  "endpoint_type": "Secondary",
  "definition": "To correlate PI3K pathway activation (e.g. PTEN low and/or PIK3CA mutation, HER 1-4 expression and/or phosphorylation) in tumor samples and pCR"
}

{
  "name": "Immune function signature correlation with pCR",
  "endpoint_type": "Secondary",
  "definition": "To correlate a gene immune function signature in tumor samples and pCR"
}

{
  "name": "Ki67 change correlation with pCR",
  "endpoint_type": "Secondary",
  "definition": "To correlate baseline and change (day 15) in Ki67 with pCR"
}

{
  "name": "pCR rate with pertuzumab/trastuzumab + taxane",
  "endpoint_type": "Secondary",
  "definition": "To determine pCR rates to preoperative pertuzumab/trastuzumab + taxane in the setting of histologically confirmed residual cancer after 12 weeks of preoperative pertuzumab/trastuzumab"
}

{
  "name": "Baseline biomarker identification",
  "endpoint_type": "Exploratory",
  "definition": "To identify baseline biomarkers that may predict sensitivity (pCR) or resistance (no pCR) to anti-HER2 therapy, such as ER, Ki67, serum methylation markers, gene expression profiles, and others to be decided"
}

{
  "name": "Serial biomarker changes",
  "endpoint_type": "Exploratory",
  "definition": "To explore changes in biomarkers (e.g., PIK3CA, ER, Ki67, serum methylation markers, gene expression profiles) through serial samples collected from baseline, end of therapy, at the time of definitive surgery and post operatively in an effort to understand resistance to anti-HER2 therapy and obtain preliminary data"
}

{
  "name": "SUV correlation with pCR in residual disease cohort",
  "endpoint_type": "Exploratory",
  "definition": "To correlate baseline and change (day 15) in SUV on FDG PET with pCR among patients with histologic confirmed residual disease after 12 weeks preoperative pertuzumab/trastuzumab and subsequent addition of standard therapy per investigator discretion"
}

