  "definition": "CRi rate per independent review"
}

{
  "name": "Duration of Remission (DOR)",
  "endpoint_type": "Secondary",
  "definition": "Time from the first CR or CRi to relapse or death from any cause in the absence of documented relapse"
}

{
  "name": "Overall survival (OS)",
  "endpoint_type": "Secondary",
  "definition": "Time from the KTE-X19 infusion to the date of death from any cause"
}

{
  "name": "Relapse-free survival (RFS)",
  "endpoint_type": "Secondary",
  "definition": "Time from the KTE-X19 infusion date to the date of disease relapse or death from any cause"
