  "endpoint_type": "Primary",
  "definition": "Confirm the MTD and safety of giving a single dose of FT596 at Day 7 post-transplant using one dose level below the MTD (MTD -1) or the MTD from Component 1"
}

{
  "name": "Adverse events related to FT596 and rituximab",
  "endpoint_type": "Secondary",
