}

{
  "name": "Non-relapse mortality",
  "endpoint_type": "Secondary",
  "definition": "Determine the incidence of non-relapse mortality at 100 days and 1 year post auto-HSCT"
}

{
  "name": "FT596 persistence",
  "endpoint_type": "Correlative",
  "definition": "Evaluate persistence of FT596 in blood after each FT596 infusion by immunophenotyping and PCR up to 1 year"
