{
  "name": "Association of FT596 persistence with safety and activity",
  "endpoint_type": "Correlative",
  "definition": "Assess the association of FT596 cell persistence with safety and anti-tumor activity"
}

{
  "name": "Association of baseline characteristics with response",
  "endpoint_type": "Correlative",
  "definition": "Assess the association of baseline clinical and tumor characteristics with safety and response endpoints following administration of FT596"
}

