{
  "name": "iPR (immune partial response)",
  "endpoint_type": "Response endpoint",
  "definition": "Partial response using iRECIST criteria - may occur after prior iUPD"
}

{
  "name": "iSD (immune stable disease)",
  "endpoint_type": "Response endpoint",
  "definition": "Stable disease using iRECIST criteria - may occur after prior iUPD"
}

{
  "name": "iUPD (immune unconfirmed progression)",
  "endpoint_type": "Progression endpoint",
  "definition": "Initial progression by RECIST 1.1 criteria requiring confirmation"
}

{
  "name": "iCPD (immune confirmed progression)",
  "endpoint_type": "Progression endpoint",
  "definition": "Confirmed progression after iUPD showing further increase or new lesions"
}

{
  "name": "iPFS (immune progression-free survival)",
  "endpoint_type": "Time-to-event endpoint",
  "definition": "Time from treatment start to confirmed progression (iCPD) or death"
}

