  "details": "ROC curves to evaluate discriminative and predictive ability of early changes in SUVmax. Sensitivity, specificity, PPV, NPV, overall accuracy and AUC with 90% confidence intervals will be estimated for the entire range of threshold values in SUVmax % reduction"
}

{
  "name": "t-test or Wilcoxon rank sum test",
  "applied_to": "Primary and secondary endpoints",
  "details": "To compare distributions of % reduction in SUVmax between pathological responders and non-responders"
}

{
  "name": "Logistic regression",
  "applied_to": "Primary and secondary endpoints",
  "details": "To determine if change of SUVmax predicts response independent of standard clinicopathologic factors such as age, tumor size, grade, and proliferation index"
}

{
  "name": "Fisher's exact test",
  "applied_to": "Secondary endpoints",
  "details": "For comparing mutation status between pathological responders and non-responders"
}

{
  "name": "Linear mixed effects models",
  "applied_to": "Secondary endpoints",
  "details": "To investigate time course of quantitative markers and how patterns differ by response status"
}

{
  "name": "McNemar's test",
  "applied_to": "Secondary endpoints",
  "details": "For paired comparisons between baseline and other time points for qualitative measures"
}

{
  "name": "Kappa statistic",
  "applied_to": "Secondary endpoints",
  "details": "To assess concordance of mutation status between ptDNA and tumor specimens"
}

{
  "name": "Bootstrap re-sampling",
  "applied_to": "Primary endpoint",
  "details": "For obtaining point estimate and confidence interval for the optimal cut point as well as internal validation"
}

{
  "name": "Surface mapping tool",
  "applied_to": "Secondary endpoints",
  "details": "Modified surface mapping tool to assign tumors to immune enriched and not-enriched groups based on expression of immune function genes"
}

{
  "name": "Kaplan-Meier method",
  "applied_to": "Long term outcomes",
  "details": "For summarizing long term outcomes (recurrence-free survival and overall survival)"
}

{
  "name": "Exact binomial test",
  "applied_to": "Primary efficacy analysis",
  "details": "Compare observed response rate to historical control rate of 20%"
}

{
  "name": "Kaplan-Meier approach",
  "applied_to": "DOR, PFS, OS",
  "details": "Time-to-event analysis with 2-sided 95% confidence intervals"
}

{
  "name": "Clopper-Pearson method",
  "applied_to": "ORR confidence intervals",
  "details": "Exact 95% confidence interval generation"
}

{
  "name": "Exact binomial test",
  "applied_to": "Primary endpoint OCR rate comparison to historical control",
  "details": "Compare observed OCR rate to 40% historical control rate, one-sided alpha 0.025"
}

{
  "name": "Kaplan-Meier method",
  "applied_to": "Time-to-event endpoints (DOR, RFS, OS)",
  "details": "Generate KM plots, median estimates, and 95% CIs"
}

{
  "name": "Clopper-Pearson method",
  "applied_to": "Confidence intervals for response rates",
  "details": "Generate exact 95% confidence intervals"
}

{
  "name": "Reverse Kaplan-Meier approach",
  "applied_to": "Follow-up time estimation",
  "details": "Estimate follow-up time for DOR"
}

{
  "name": "Modified Continual Reassessment Method (CRM)",
  "applied_to": "Dose escalation for both components",
  "details": "Power model for probability of DLT, target toxicity rate \u226425%, uses Bayesian framework"
}

{
  "name": "Immunophenotyping",
  "applied_to": "FT596 persistence evaluation",
  "details": "Flow cytometry analysis of PBMC to detect surface markers and intracellular markers"
}

{
  "name": "PCR testing",
  "applied_to": "FT596 persistence evaluation",
  "details": "PCR testing for FT596 persistence up to 1 year"
}

{
  "name": "iRECIST criteria",
  "applied_to": "Response assessment in immunotherapy trials",
  "details": "Modified RECIST 1.1 allowing for pseudoprogression patterns, requires confirmation of initial progression"
}

{
  "name": "RECIST 1.1",
  "applied_to": "Primary response endpoints",
  "details": "Standard response criteria - recommended to continue as primary for randomized licensing trials"
}

